     * $query->filterByValorHuella('%fooValue%'); // WHERE VALOR_HUELLA LIKE '%fooValue%'
     * </code>
     *
     * @param     string $valorHuella The value to use as filter.
     *              Accepts wildcards (* and % trigger a LIKE)
     * @param     string $comparison Operator to use for the column comparison, defaults to Criteria::EQUAL
     *
     * @return ContenidoUnidadDocumentalQuery The current query, for fluid interface
     */
    public function filterByValorHuella($valorHuella = null, $comparison = null)
    {
        if (null === $comparison) {
            if (is_array($valorHuella)) {
                $comparison = Criteria::IN;
            } elseif (preg_match('/[\%\*]/', $valorHuella)) {
                $valorHuella = str_replace('*', '%', $valorHuella);
                $comparison = Criteria::LIKE;
            }
        }

        return $this->addUsingAlias(ContenidoUnidadDocumentalPeer::VALOR_HUELLA, $valorHuella, $comparison);
    }

